// 1. Setup bpmn-js in your project (see SETUP.md for details)
// 2. Use the following BPMN XML as the initial diagram:

const initialDiagram = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
                  xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"
                  xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"
                  id="Definitions_1"
                  targetNamespace="http://bpmn.io/schema/bpmn">
  <bpmn:process id="Process_1" isExecutable="false">
    <bpmn:startEvent id="StartEvent_1" />
    <bpmn:exclusiveGateway id="Gateway_1" default="Flow_2" />
    <bpmn:task id="Task_1" />
    <bpmn:endEvent id="EndEvent_1" />
    <bpmn:endEvent id="EndEvent_2" />
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Gateway_1" />
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Gateway_1" targetRef="Task_1" />
    <bpmn:sequenceFlow id="Flow_3" sourceRef="Gateway_1" targetRef="EndEvent_2" />
    <bpmn:sequenceFlow id="Flow_4" sourceRef="Task_1" targetRef="EndEvent_1" />
  </bpmn:process>
</bpmn:definitions>`;

// 3. Load this diagram into the bpmn-js modeler
import BpmnModeler from 'bpmn-js/lib/Modeler';

const modeler = new BpmnModeler({ container: '#canvas' });
modeler.importXML(initialDiagram);

// 4. In the UI, select the non-default flow (Flow_3),
//    drag a Timer Intermediate Catch Event from the palette and drop it onto Flow_3.
//    (This can also be done programmatically, but the bug is UI-driven.)

// 5. Inspect the XML or the model after the operation:
//    The 'default' attribute on the exclusive gateway will be removed,
//    but the default flow will still be visually rendered as default.

// 6. To check programmatically:
modeler.saveXML({ format: true }, function(err, xml) {
  // Search for 'default="Flow_2"' in the xml string
  // It should be missing after the bug is triggered
  console.log(xml);
});
